import React, { useState } from "react";
import { Card, CardContent, Typography, Slider, Button, TextField } from "@mui/material";
import { ElectricBolt, DirectionsCar, FlightTakeoff, Home } from "@mui/icons-material";

const CarbonDataInput = () => {
  const [electricity, setElectricity] = useState(0);
  const [milesDriven, setMilesDriven] = useState(0);
  const [flights, setFlights] = useState(0);
  const [householdSize, setHouseholdSize] = useState(1);

  const handleSubmit = () => {
    const carbonData = { electricity, milesDriven, flights, householdSize };
    console.log("Submitted Carbon Data:", carbonData);
    alert("Data submitted successfully!");
  };

  return (
    <div style={{ maxWidth: 600, margin: "auto", padding: 20 }}>
      <Typography variant="h4" align="center" gutterBottom>
        Carbon Footprint Input
      </Typography>

      {/* Electricity Usage */}
      <Card style={{ marginBottom: 20 }}>
        <CardContent>
          <Typography variant="h6"><ElectricBolt /> Electricity Usage (kWh/month)</Typography>
          <Slider value={electricity} onChange={(e, v) => setElectricity(v)} min={0} max={1000} step={10} />
        </CardContent>
      </Card>

      {/* Miles Driven */}
      <Card style={{ marginBottom: 20 }}>
        <CardContent>
          <Typography variant="h6"><DirectionsCar /> Miles Driven Per Month</Typography>
          <Slider value={milesDriven} onChange={(e, v) => setMilesDriven(v)} min={0} max={3000} step={10} />
        </CardContent>
      </Card>

      {/* Flights Taken */}
      <Card style={{ marginBottom: 20 }}>
        <CardContent>
          <Typography variant="h6"><FlightTakeoff /> Flights Taken This Year</Typography>
          <Slider value={flights} onChange={(e, v) => setFlights(v)} min={0} max={20} step={1} />
        </CardContent>
      </Card>

      {/* Household Size */}
      <Card style={{ marginBottom: 20 }}>
        <CardContent>
          <Typography variant="h6"><Home /> Household Size</Typography>
          <TextField
            type="number"
            value={householdSize}
            onChange={(e) => setHouseholdSize(e.target.value)}
            inputProps={{ min: 1 }}
            fullWidth
          />
        </CardContent>
      </Card>

      {/* Submit Button */}
      <Button variant="contained" color="primary" fullWidth onClick={handleSubmit}>
        Submit Carbon Data
      </Button>
    </div>
  );
};

export default CarbonDataInput;
